+
+  EXPECT_TRUE(result.rows->Next());
+  EXPECT_EQ(result.rows->ColumnValue(0), String("tok2"));
+  EXPECT_EQ(result.rows->ColumnValue(1), String("tok2-renewed"));
+  EXPECT_FALSE(result.rows->ColumnValue(2).is_null());
