+      name_and_types, "expression index columns", &dependent_column_names,
+      /*dependent_sequences=*/nullptr,
+      /*allow_volatile_expression=*/false, &udf_dependencies,
+      /*is_pending_commit_timestamp=*/nullptr, &column_type));
+  return column_type;
+}
