+      UpdateSchema(schema.get(), {R"(
+      ALTER QUEUE myqueue ADD ROW DELETION POLICY (
+        OLDER_THAN(CreateTime, INTERVAL 3 DAY)
+      )
+    )"}),
+      StatusIs(error::RowDeletionPolicyAlreadyExists("CreateTime", "myqueue")));
